# DK RAR.  Randers - Ryomgård
#
let rr = path("d3.dk.rar");

with detail = 3, railway = :first :pax :removed {
    # point.dk.Randers  dk.FFH

    with link = "line.dk.RAR" {
        track(:lor:ror,
                rr[:ran.yh - 0.1dl, :ran.yh] << 0.5md << 1ms << 0.5mt
            ..  rr[:str.yr, :str.yr + 0.1dl]
        );
        track(rr[:str.yr, :str - 0.49sw]);
    }

    with link = "line.dk.RAR" {
        let ran = path("d3.dk.rar.ran");

        track(:lor:ror,
                ran[:ran.yr - 0.1ld, :ran.yr] << 0.5md >> 0.5mt
            ..  ran[:ran.xr + 1mt, :str.yr]
        );
    }
}

with detail = 3, railway = :first :pax :closed {
    with link = "point.dk.Strømmen", railway = :station {
        track(rr[:str - 0.5sw, :str + 0.5sw]);
        marker(:left :de.bf, rr[:str] << 0.5mt);
        slabel(:bottom, rr[:str] >> 0.5mt + (0dt, 150m) + (3dt, 0.2dt),
            "Strømmen"
        );
    }

    with link = "line.dk.RAR" {
        track(rr[:str + 0.49sw, :str + 1.81km]);
        line_label(:right:nw, rr[:str + 1.8km] >> 0.5mt, "RAR");
        track(rr[:str + 1.79km, :rom - 0.49sw]);
    }

    with link = "point.dk.Romalt", railway = :station {
        track(rr[:rom - 0.5sw, :rom + 0.5sw]);
        marker(:left :de.hp :removed, rr[:rom] << 0.5mt);
        slabel(:top :removed, rr[:rom] << 0.5mt << 1sh + (0.3dt, -0.2dt),
            "Romalt"
        );
    }

    with link = "line.dk.RAR" {
        track(rr[:rom + 0.49sw, :vol - 0.49sw]);
    }

    with link = "point.dk.Volkmølle", railway = :station {
        track(rr[:vol - 0.5sw, :vol + 0.5sw]);
        marker(:right :de.bf :removed, rr[:vol] >> 0.5mt);
        slabel(:bottom :removed, rr[:vol] >> 0.5mt >> 1sh + (1dt, 0.4dt),
            "Volkmølle"
        );
    }

    with link = "line.dk.RAR" {
        track(rr[:vol + 0.49sw, :ugg - 0.49sw]);
    }

    with link = "point.dk.Uggelhuse", railway = :station {
        track(rr[:ugg - 0.5sw, :ugg + 0.5sw]);
        marker(:left :de.bf :removed, rr[:ugg] << 0.5mt);
        slabel(:top :removed, rr[:ugg] << 0.5mt << 1sh + (0.3dt, -0.4dt),
            "Uggelhuse"
        );
    }

    with link = "line.dk.RAR" {
        track(rr[:ugg + 0.49sw, :flo - 0.49sw]);
    }

    with link = "point.dk.Floes", railway = :station {
        track(rr[:flo - 0.5sw, :flo + 0.5sw]);
        marker(:left :de.hst :removed, rr[:flo] << 0.5mt);
        slabel(:top :removed, rr[:flo] << 0.5mt << 1sh + (0.3dt, -0.3dt),
            "Floes"
        );
    }

    with link = "line.dk.RAR" {
        track(rr[:flo + 0.49sw, :flo + 2.11km]);
        line_label(:right:n, rr[:flo + 2.1km] >> 0.5mt, "RAR");
        track(rr[:flo + 2.09km, :all - 0.49sw]);
    }

    with link = "point.dk.Allingåbro", railway = :station {
        track(rr[:all - 0.5sw, :all + 0.5sw]);
        marker(:left :de.bf, rr[:all] << 0.5mt);
        slabel(:top :bold, rr[:all] << 0.5mt << 1sh + (0.3dt, -0.5dt),
            "Allingåbro"
        );
    }
}

with detail = 3, railway = :first :pax :removed {
    with link = "line.dk.RAR" {
        track(rr[:all + 0.49sw, :aun - 0.49sw]);
    }

    with link = "point.dk.Auning", railway = :station {
        track(rr[:aun - 0.5sw, :aun + 0.5sw]);
        marker(:right :de.bf, rr[:aun] >> 0.5mt);
        slabel(:left, rr[:aun] >> 0.5mt >> 1sh + (-1.5dt, 1.3dt),
            "Auning"
        );
    }

    with link = "line.dk.RAR" {
        track(rr[:aun + 0.49sw, :pin - 0.49sw]);
    }

    with link = "point.dk.Pindstrup", railway = :station {
        track(rr[:pin - 0.5sw, :pin + 0.5sw]);
        marker(:left :de.bf, rr[:pin] << 0.5mt);
        slabel(:right, rr[:pin] << 0.5mt << 1sh + (-2dt, -1.2dt),
            "Pindstrup"
        );
    }

    with link = "line.dk.RAR" {
        track(rr[:pin + 0.49sw, :pin + 2.01km]);
        line_label(:right:n, rr[:pin + 2km] >> 0.5mt, "RAR");
        track(rr[:pin + 1.99km, :ryo.yr - 0.79seg]);
        track(:station, rr[:ryo.yr - 0.8seg, :ryo.yr + 0.1dl]);
    }

    # point.dk.Ryomgård  dk.AHG
}

